package com.example.starter.incident;

/**
 * 处置任务状态机：OPEN → STARTED → DONE/CANCELLED，或 OPEN → CANCELLED。
 * OPEN → STARTED 必须持有覆盖所需共享资源的 ACTIVE 租约；
 * DONE 与 CANCELLED 均为终态，不允许任何后续流转。
 */
public enum TaskStatus {

    /** 待处理，尚未开始；可申请/持有 ACTIVE 租约，但未进入执行。 */
    OPEN,

    /** 已开始：持有有效 ACTIVE 租约后才可进入，进行中不可被抢占。 */
    STARTED,

    /** 已完成（STARTED 后完成；完成时原子释放全部 ACTIVE 租约）。 */
    DONE,

    /** 已取消（OPEN 或 STARTED 均可取消；取消时原子释放全部 ACTIVE 租约）。 */
    CANCELLED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置任务实体，对应 incident_tasks 表。
 * (incidentId, taskKey) 唯一，同键同内容幂等，同键不同内容冲突；
 * 每事件至多 20 个任务。version 为乐观版本（创建为 0，开始/完成/取消递增），
 * 租约申请与抢占必须提交当前版本。doneBy/doneAt 仅 DONE 有值，
 * cancelledBy/cancelledAt 仅 CANCELLED 有值，startedAt 仅 STARTED/DONE 有值。
 * 时间均为 UTC。
 */
public record IncidentTask(
        long id,
        long incidentId,
        String taskKey,
        String groupCode,
        String title,
        TaskStatus status,
        long version,
        String createdBy,
        String doneBy,
        Instant doneAt,
        String cancelledBy,
        Instant cancelledAt,
        Instant startedAt,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 判断两条任务的业务内容是否一致（用于 taskKey 幂等比对；阻塞事件集合另行比对）。
     */
    public boolean sameContent(String groupCode, String title) {
        return this.groupCode.equals(groupCode) && this.title.equals(title);
    }
}

