import com.example.starter.incident.dto.Responses.PreemptionClosureView;
import com.example.starter.incident.dto.Responses.PreemptionView;
import com.example.starter.incident.dto.Responses.ResourceUsageView;
import com.example.starter.incident.dto.Responses.ResourceView;

/**
 * 跨事件共享资源租约与依赖感知抢占服务。
 * 容量判定、抢占闭包与租约写入均在 resource_lock 单行锁内同事务完成，
 * 任务开始额外用条件更新兜底，保证容量永不超限且任务不带失效租约启动。
 */
@Service
public class ResourceService {

    private final Clock clock;

    public ResourceService(Clock clock) {
        this.clock = clock;
    }

    /** 创建共享资源：resourceKey 全局唯一，capacity 为正整数。 */
    @Transactional
    public ResourceView createResource(ResourceCreateRequest req) {
        throw new UnsupportedOperationException();
    }

    /** 查询资源列表（只读）。 */
    @Transactional(readOnly = true)
    public java.util.List<ResourceView> listResources() {
        throw new UnsupportedOperationException();
    }

    /** 查询资源占用明细（资源本体 + 当前全部 ACTIVE 租约，只读）。 */
    @Transactional(readOnly = true)
    public ResourceUsageView resourceUsage(String resourceKey) {
        throw new UnsupportedOperationException();
    }

    /** 当前指挥人为 OPEN 且未开始的任务申请租约。 */
    @Transactional
    public LeaseView acquireLease(String incidentKey, String taskKey, String actor,
                                  LeaseAcquireRequest req) {
        throw new UnsupportedOperationException();
    }

    /** 仅持有有效 ACTIVE 租约的 OPEN 任务可开始。 */
    @Transactional
    public com.example.starter.incident.dto.Responses.TaskView startTask(
            String incidentKey, String taskKey, String actor, TaskStartRequest req) {
        throw new UnsupportedOperationException();
    }

    /** 高优先级事件提交抢占计划，整单成功或整单 409/422。 */
    @Transactional
    public PreemptionView preempt(String incidentKey, String actor, PreemptRequest req) {
        throw new UnsupportedOperationException();
    }

    /** 只读计算抢占闭包：列出必须同时抢占的全部受害租约。 */
