     * 按业务键锁定租约行并关联业务键（对 resource_leases 行 FOR UPDATE）。
     */
    public Optional<LeaseRow> lockLeaseRowByKey(String leaseKey) {
        List<LeaseRow> rows = jdbc.query(
                "SELECT l.*, r.resource_key, i.incident_key, t.task_key" + LEASE_JOIN
                        + " WHERE l.lease_key = ? FOR UPDATE", new LeaseRowMapper("l"), leaseKey);
        return rows.stream().findFirst();
    }

    /** 查询资源全部租约行（任意状态，历史查询用），按租约 id 返回。 */
    public List<LeaseRow> listLeaseRowsForResource(long resourceId) {
        return jdbc.query(
                "SELECT l.*, r.resource_key, i.incident_key, t.task_key" + LEASE_JOIN
                        + " WHERE l.resource_id = ? ORDER BY l.id",
                new LeaseRowMapper("l"), resourceId);
    }

    /** 查询事件全部租约行（任意状态），按租约 id 返回。 */
    public List<LeaseRow> listLeaseRowsForIncident(long incidentId) {
        return jdbc.query(
